const turno = $('Normalizar correo').first().json;
if (!turno.sessionId) throw new Error('El correo no contiene threadId');
const filas = $input.all().map(item => item.json).filter(row => row.id);
if (filas.length > 1) throw new Error('Hay más de una ficha para esta sesión');
const registro = filas[0] ?? {};
const campos = registro.fields ?? registro;
const nombre = String(campos.Nombre ?? '').trim();
const apellido = String(campos.Apellido ?? '').trim();
const ultimaPregunta = nombre && !apellido ? '¿Cuál es tu apellido?' :
  apellido && !nombre ? '¿Cuál es tu nombre?' : '';
return [{json: {
  session_id: turno.sessionId,
  mensaje_actual: String(turno.chatInput ?? '').trim(),
  nombre, apellido, ultima_pregunta: ultimaPregunta,
  consulta_pendiente: String(campos['Consulta pendiente'] ?? ''),
  identidad_completa: Boolean(nombre && apellido),
  registro
}}];

const contexto = $('Preparar contexto').first().json;
const entrada = $input.first().json;

// Information Extractor devuelve sus campos dentro de output.
const extraido = contexto.identidad_completa
  ? {}
  : entrada.output;

if (
  !contexto.identidad_completa &&
  (!extraido || typeof extraido !== 'object')
) {
  throw new Error('El extractor no devolvió el objeto output esperado');
}

const limpiar = valor => String(valor ?? '').trim();

const nombre =
  limpiar(extraido.nombre) || contexto.nombre;

const apellido =
  limpiar(extraido.apellido) || contexto.apellido;

const ambiguo = extraido.requiere_aclaracion === true;

const puede_continuar =
  Boolean(nombre && apellido) && !ambiguo;

// Si ya estaba identificado, todo el mensaje actual
// se entrega al agente de atención.
const consultaNueva = contexto.identidad_completa
  ? contexto.mensaje_actual
  : limpiar(extraido.consulta_nueva);

const consultaPendiente = [
  contexto.consulta_pendiente,
  consultaNueva
].filter(Boolean).join('\n');

let pregunta = '';

if (!puede_continuar) {
  if (ambiguo) {
    pregunta =
      'Para registrarte correctamente, ¿podés indicar ' +
      'tu nombre y tu apellido por separado?';
  } else if (!nombre && !apellido) {
    pregunta =
      '¡Hola! Antes de seguir, ¿me indicás tu nombre y apellido?';
  } else if (!nombre) {
    pregunta = 'Gracias. ¿Cuál es tu nombre?';
  } else {
    pregunta = `Gracias, ${nombre}. ¿Cuál es tu apellido?`;
  }
}

return [{
  json: {
    session_id: contexto.session_id,
    nombre,
    apellido,
    ultima_pregunta: pregunta,
    consulta_pendiente: consultaPendiente,
    puede_continuar,
    hay_consulta: Boolean(consultaPendiente.trim()),
    chatInput: consultaPendiente,
    respuesta_identificacion: pregunta,
    respuesta_bienvenida:
      `Gracias, ${nombre}. ¿En qué podemos ayudarte?`
  }
}];

