const registro = $("Call OC - Identificar contacto1").first().json.registro;
const campos = registro.fields ?? registro;
const identidad = $('Call OC - Identificar contacto1').first().json;
if (!registro.id) throw new Error('Falta el ID de la ficha de Airtable');
return [{json: {
  ficha_id: registro.id,
  nombre: [identidad.nombre_firstItem, identidad.apellido_firstItem].join(' '),
  estado: campos['Estado del caso'] ?? 'Recibido',
  resumen: campos['Resumen consolidado'] ?? '',
  datos_clave: campos['Datos clave'] ?? '',
  proximo_paso: campos['Proximo paso'] ?? '',
  mensajes: Number(campos['Cantidad de mensajes'] ?? 0)
}}];

const historial = $input.all().map(item => item.json).filter(item => Object.keys(item).length);
if (!historial.length) throw new Error('La mesa no devolvió mensajes');
return [{json:{historial, resumen_previo: $('Ficha').first().json.resumen}}];

