={{ (() => {
  const salida = $('AI Agent1').first().json.output;
  const respuestas = Array.isArray(salida.respuestas) ? salida.respuestas : [salida];
  return respuestas.map(r => {
    if (r.Respuesta == null) return 'No encontré información oficial para una de tus consultas.';
    return r.Respuesta + (r.Articulo ? ' (' + r.Articulo + ')' : '');
  }).join('\n\n');
})() }}

