return $input.all().map((item, index) => {
  const mail = item.json;
  const headers = mail.headers ?? {};
  const subject = String(mail.subject ?? mail.Subject ?? headers.subject ?? '').replace(/^subject:\s*/i, '');
  const from = mail.from?.value?.[0]?.address ?? mail.from?.text ?? (typeof mail.from === 'string' ? mail.from : undefined) ?? mail.From ?? headers.from ?? '';
  const fromEmail = String(from).match(/<([^>]+)>/)?.[1] ?? String(from).replace(/^from:\s*/i, '').trim();
  const htmlText = typeof mail.html === 'string'
    ? mail.html.split(/<blockquote|class=["']gmail_quote/i)[0].replace(/<br\s*\/?\s*>|<\/(?:p|div)>/gi, '\n').replace(/<[^>]*>/g, '')
    : '';
  const text = String(mail.text || mail.textPlain || htmlText).split(/\r?\n/);
  const quoteStart = text.findIndex((line, lineIndex) => {
    if (/^\s*(>|[- ]*Original Message[- ]*|[- ]*Mensaje original[- ]*)/i.test(line)) return true;
    if (!/^\s*(On|El)\s/i.test(line)) return false;
    const possibleHeader = text.slice(lineIndex, lineIndex + 3).join(' ');
    return /^\s*(?:On\s+.+?\bwrote:|El\s+.+?\bescribi[oó]:)/i.test(possibleHeader);
  });
  const chatInput = (quoteStart < 0 ? text : text.slice(0, quoteStart)).join('\n').trim();
  const blocked = /out of office|fuera de oficina|auto-reply|automatic reply|undeliverable|no reply|mailer-daemon|mailer-deamon/i.test(subject);
  return {
    json: {subject, fromEmail, chatInput, gmailMessageId: mail.id, gmailThreadId: mail.threadId, sessionId: mail.threadId ? 'gmail:' + mail.threadId : null, blocked},
    pairedItem: {item: index},
  };
});
